preConditionHook:
// The stop sits beyond the worst price the trade has seen SO FAR, read as of
// the previous bar: the extreme through bar [1], compared against this bar's
// close. Including the current bar (the merged pseudocode's
// lowest(low, BarsSinceEntry + 1)[0]) can never fire on the long side, because
// that low is always <= this close, so the level is taken before the current
// bar is folded in.
// Running min/max rather than a window whose length is the position's age:
// same values, deepest subscript 0 instead of the longest trade.
// BarsSinceEntry() is 0 on the fill bar AND while flat, so the seed branch
// re-arms every flat bar and lands on the entry bar's own extremes.
if (el_eq((double)ctx.BarsSinceEntry(), 0.0)) {
    lowSinceEntry = low[0];
    highSinceEntry = high[0];
    stopLongLevel = low[0] - ratchetOffset;
    stopShortLevel = high[0] + ratchetOffset;
} else {
    stopLongLevel = lowSinceEntry - ratchetOffset;
    stopShortLevel = highSinceEntry + ratchetOffset;
    // Strict comparison, as EL's own Extremes uses: a tie keeps the earlier bar.
    if (el_lt(low[0], lowSinceEntry)) lowSinceEntry = low[0];
    if (el_gt(high[0], highSinceEntry)) highSinceEntry = high[0];
}
